import type { Declaration, Field, Model, TypeRef } from '#src/model'
import { snake } from '#src/names'

export const NAMESPACE = '::session_bridge'

export const BANNER = (source: string): string =>
  [
    '// Generated by @session/bridge-codegen from ' + source + '. Do not edit by hand:',
    '// change the TypeScript and run `pnpm codegen`.',
  ].join('\n')

export function doc(lines: string[], indent = ''): string {
  return lines.map((line) => `${indent}///${line ? ' ' + line : ''}\n`).join('')
}

/**
 * The C++ spelling of a TypeScript type reference, fully qualified so it reads the same anywhere.
 */
export function cppType(type: TypeRef): string {
  switch (type.kind) {
    case 'string':
      return 'std::string'
    case 'number':
      return 'double'
    case 'boolean':
      return 'bool'
    case 'bytes':
      return 'std::vector<std::byte>'
    case 'secret':
      return `${NAMESPACE}::SecretBytes`
    case 'enum':
    case 'struct':
    case 'union':
      return `${NAMESPACE}::${type.name}`
    case 'array':
      return `std::vector<${cppType(type.element)}>`
  }
}

export function fieldType(field: Field): string {
  const inner = cppType(field.type)
  return field.optional ? `std::optional<${inner}>` : inner
}

export const member = (field: Field): string => snake(field.name)

export function forEachDeclaration(
  model: Model,
  visit: { [K in Declaration['kind']]: (declaration: Extract<Declaration, { kind: K }>) => string },
): string {
  return model.declarations
    .map((declaration) => {
      switch (declaration.kind) {
        case 'enum':
          return visit.enum(declaration)
        case 'struct':
          return visit.struct(declaration)
        case 'union':
          return visit.union(declaration)
      }
    })
    .join('\n')
}
